PREFIX brick: <http://brickschema.org/>
PREFIX ref: <http://w3id.org/brick/ref/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?point ?tsid ?cls WHERE {
  ?point a brick:ElectricPower ;
         brick:hasTag "CondPump02" .
}

PREFIX brick: <http://brickschema.org/>
